/**
 * ModeSwitch's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in both shells.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/mode-switch.ts`. Never edit it by hand.
 */
import { h, reactive } from 'vue'

import type { ComponentStates } from '@polymorph/vue'

import ModeSwitch from './ModeSwitch.vue'

export const states: ComponentStates = {
  component: 'ModeSwitch',
  entries: [
    {
      name: 'uncontrolled — the document’s preference',
      render: (overrides = {}) => h(ModeSwitch, { label: 'Appearance', ...overrides }),
      expect: { role: 'radiogroup', 'data-size': 'md' },
    },
    {
      name: 'controlled — the application holds the choice',
      render: (overrides = {}) =>
        h({
          setup() {
            const held = reactive({ value: 'light' as 'light' | 'dark' | 'system' })
            return () => [
              h(ModeSwitch, {
                label: 'Appearance',
                value: held.value,
                onChange: (value: typeof held.value) => {
                  held.value = value
                },
                ...overrides,
              }),
            ]
          },
        }),
      expect: { role: 'radiogroup' },
    },
    {
      name: 'sm',
      render: (overrides = {}) =>
        h(ModeSwitch, { label: 'Appearance', value: 'dark', size: 'sm', ...overrides }),
      expect: { 'data-size': 'sm' },
    },
    {
      name: 'disabled — while the application saves the last choice',
      render: (overrides = {}) =>
        h(ModeSwitch, { label: 'Appearance', value: 'system', disabled: true, ...overrides }),
      expect: { 'data-disabled': '' },
    },
    {
      name: 'localized',
      render: (overrides = {}) =>
        h(ModeSwitch, {
          label: 'Apparence',
          value: 'light',
          messages: { light: 'Clair', dark: 'Sombre', system: 'Système' },
          ...overrides,
        }),
    },
  ],
}
